namespace AccountsAPIs.Entities;

/// <summary>
/// Represents a payment transaction, capturing essential details such as amount, status, 
/// customer contact information, and the associated payment method. 
/// Supports multi-tenant architecture via a tenant identifier.
/// </summary>
public class PaymentHistory : BaseEntity
{
    /// <summary>
    /// Gets or sets the tenant identifier used for multi-tenancy filtering.
    /// </summary>
    public Guid TenantId { get; set; }

    /// <summary>
    /// Gets or sets the unique payment identifier generated by Razorpay.
    /// </summary>
    public string? RazorpayPaymentId { get; set; }

    /// <summary>
    /// Gets or sets the unique order identifier linked to this payment.
    /// </summary>
    public string? OrderId { get; set; }

    /// <summary>
    /// Gets or sets the unique invoice identifier for this payment transaction.
    /// </summary>
    public string? InvoiceId { get; set; }

    /// <summary>
    /// Gets or sets the total amount paid for the transaction.
    /// </summary>
    public decimal Amount { get; set; }

    /// <summary>
    /// Gets or sets the currency type in which the payment was made (e.g., INR, USD).
    /// </summary>
    public CurrencyTypesEnum? Currency { get; set; }

    /// <summary>
    /// Gets or sets the current processing status of the payment (e.g., Captured, Failed).
    /// </summary>
    public PaymentStatusTypesEnum? Status { get; set; }

    /// <summary>
    /// Gets or sets a value indicating whether the payment was successfully captured.
    /// </summary>
    public bool Captured { get; set; }

    /// <summary>
    /// Gets or sets the transaction fee applied by the payment gateway.
    /// </summary>
    public decimal Fee { get; set; }

    /// <summary>
    /// Gets or sets the tax amount applied to the transaction.
    /// </summary>
    public decimal Tax { get; set; }

    /// <summary>
    /// Gets or sets an optional description or note related to the payment.
    /// </summary>
    public string? Description { get; set; }

    /// <summary>
    /// Gets or sets the payer’s email address.
    /// </summary>
    public string? Email { get; set; }

    /// <summary>
    /// Gets or sets the payer’s contact number.
    /// </summary>
    public string? Contact { get; set; }

    /// <summary>
    /// Gets or sets the foreign key referencing the associated payment method.
    /// </summary>
    public Guid? PaymentMethodId { get; set; }

    /// <summary>
    /// Navigation property for the payment method used in this transaction.
    /// </summary>
    [ForeignKey("PaymentMethodId")]
    public virtual PaymentMethod? PaymentMethod { get; set; }

    /// <summary>
    /// Gets or sets the foreign key referencing the related subscription billing detail.
    /// </summary>
    public Guid? BillingDetailId { get; set; }

    /// <summary>
    /// Navigation property for the subscription billing detail associated with this payment.
    /// </summary>
    [ForeignKey("BillingDetailId")]
    public virtual BillingDetail? BillingDetail { get; set; }
}